107→/// Login to Spice.ai using OAuth flow or direct API key.
108→async fn login_spiceai(_ctx: &RuntimeContext, api_key: Option<String>) -> Result<()> {
109→    if let Some(key) = api_key {
110→        // Direct API key authentication
111→        merge_auth_config("SPICEAI", &[("API_KEY", key.as_str())])?;
112→        println!("\x1b[32mSuccessfully logged in to Spice.ai with API key\x1b[0m");
113→        return Ok(());
114→    }
115→
116→    // Spice.ai OAuth flow
117→    let base_url = get_spice_base_url();
118→    let auth_code = generate_auth_code();
119→
120→    let auth_url = format!("{base_url}/auth/token?code={auth_code}");
121→
122→    println!("Attempting to open Spice.ai authorization page in your default browser");
123→    println!("\nYour auth code:\n");
124→    println!("{}-{}", &auth_code[..4], &auth_code[4..]);
125→    println!("\nIf the browser does not open, visit the following URL manually:");
126→    println!("\n{auth_url}\n");
127→
128→    // Try to open browser automatically
129→    let _ = open::that(&auth_url);
130→
131→    tracing::info!("Waiting for authentication...");
132→
133→    // Poll for auth status
134→    let client = reqwest::Client::new();
135→    let exchange_url = format!("{base_url}/auth/token/exchange");
136→
137→    let access_token = loop {
138→        tokio::time::sleep(std::time::Duration::from_secs(1)).await;
139→
140→        let response = client
141→            .post(&exchange_url)
142→            .header("Content-Type", "application/json")
143→            .json(&serde_json::json!({ "code": auth_code }))
144→            .send()
145→            .await;
146→
147→        let response = match response {
148→            Ok(r) => r,
149→            Err(e) => {
150→                tracing::error!("Error exchanging auth code with spice.ai: {e}");
151→                continue;
152→            }
153→        };
154→
155→        let body: serde_json::Value = match response.json().await {
156→            Ok(v) => v,
157→            Err(e) => {
158→                tracing::error!("Error parsing exchange response: {e}");
159→                continue;
160→            }
161→        };
162→
163→        if body["access_denied"].as_bool().unwrap_or(false) {
164→            return Err(crate::error::Error::InvalidArgument {
165→                message: "Access denied".to_string(),
166→            });
167→        }
168→
169→        if let Some(token) = body["access_token"].as_str()
170→            && !token.is_empty()
171→        {
172→            break token.to_string();
173→        }
174→    };
175→
176→    // Try to read spicepod.yaml for preferred org/app
177→    let (org_name, app_name) = read_spicepod_metadata();
178→
179→    // Get auth context
180→    let auth_context = get_spice_auth_context(
181→        &base_url,
182→        &access_token,
183→        org_name.as_deref(),
184→        app_name.as_deref(),
185→    )
186→    .await?;
187→
188→    // Save credentials
189→    merge_auth_config(
190→        "SPICEAI",
191→        &[
192→            ("TOKEN", &access_token),
193→            ("API_KEY", &auth_context.app_api_key.unwrap_or_default()),
194→        ],
195→    )?;
196→
197→    println!(
198→        "\x1b[32mSuccessfully logged in to Spice.ai as {} ({})\x1b[0m",
199→        auth_context.username, auth_context.email
200→    );
201→    println!(
202→        "\x1b[32mUsing app {}/{}\x1b[0m",
203→        auth_context.org_name,
204→        auth_context.app_name.unwrap_or_default()
205→    );
206→
207→    Ok(())
208→}
