 17→//! Authentication configuration management.
 18→//!
 19→//! Handles reading and writing credentials to .env or .env.local files.
 20→
 21→use crate::error::{ConfigIoSnafu, Result};
 22→use snafu::ResultExt;
 23→use std::collections::HashMap;
 24→use std::path::Path;
 25→
 26→/// Merge authentication configuration into the .env file.
 27→///
 28→/// Credentials are stored with the format: `SPICE_{AUTH_TYPE}_{PARAM}=value`
 29→///
 30→/// # Arguments
 31→///
 32→/// * `auth_type` - The authentication type (e.g., "DREMIO", "S3", "PG")
 33→/// * `params` - Key-value pairs of authentication parameters
 34→///
 35→/// # Errors
 36→///
 37→/// Returns an error if the .env file cannot be read or written.
 38→pub fn merge_auth_config(auth_type: &str, params: &[(&str, &str)]) -> Result<()> {
 39→    // Determine which env file to use
 40→    let env_file = if Path::new(".env.local").exists() {
 41→        ".env.local"
 42→    } else {
 43→        ".env"
 44→    };
 45→
 46→    // Read existing env vars (ignore errors - file might not exist)
 47→    let mut env_vars: HashMap<String, String> = if Path::new(env_file).exists() {
 48→        read_env_file(env_file).unwrap_or_default()
 49→    } else {
 50→        HashMap::new()
 51→    };
 52→
 53→    // Add new auth params
 54→    for (key, value) in params {
 55→        let secret_key = format!("SPICE_{auth_type}_{key}");
 56→        env_vars.insert(secret_key, (*value).to_string());
 57→    }
 58→
 59→    // Write back to file
 60→    write_env_file(env_file, &env_vars)?;
 61→
