339→        && !token.is_empty()
340→    {
341→        return Ok(token);
342→    }
343→
344→    // Try .env.local first, then .env
345→    let env_file = if std::path::Path::new(".env.local").exists() {
346→        ".env.local"
347→    } else {
348→        ".env"
349→    };
350→
351→    if let Ok(content) = std::fs::read_to_string(env_file) {
352→        for line in content.lines() {
353→            if let Some(value) = line.strip_prefix("SPICE_SPICEAI_TOKEN=") {
354→                let token = value.trim_matches('"').trim_matches('\'').to_string();
355→                if !token.is_empty() {
356→                    return Ok(token);
357→                }
358→            }
359→        }
360→    }
361→
362→    InvalidArgumentSnafu {
363→        message: "Not authenticated. Run 'spice cloud login' to authenticate with Spice Cloud",
364→    }
365→    .fail()
366→}
