368→pub fn parse_org_app(org_app: &str) -> (String, String) {
369→    if let Some((org, app)) = org_app.split_once('/') {
370→        (org.to_string(), app.to_string())
371→    } else {
372→        (String::new(), org_app.to_string())
373→    }
374→}
