376→/// Convert a [`spice_cloud_client::error::Error`] into the CLI error type.
377→fn into_cli(e: spice_cloud_client::error::Error) -> crate::error::Error {
378→    use spice_cloud_client::error::Error as CloudError;
379→    match e {
380→        CloudError::Unauthorized { message } => crate::error::Error::InvalidArgument {
381→            message: format!("Unauthorized: {message}. Run 'spice cloud login' to re-authenticate"),
382→        },
383→        CloudError::Forbidden { message } => crate::error::Error::InvalidArgument {
384→            message: format!("Forbidden: {message}"),
385→        },
386→        CloudError::NotFound { message } => crate::error::Error::InvalidResponse {
387→            message: format!("Not found: {message}"),
388→        },
389→        CloudError::Conflict { message } => crate::error::Error::InvalidResponse {
390→            message: format!("Conflict: {message}"),
391→        },
392→        CloudError::Api { status, message } => crate::error::Error::InvalidResponse {
393→            message: format!("Request failed with status {status}: {message}"),
394→        },
395→        CloudError::HttpRequest { source } => crate::error::Error::HttpRequestFailed { source },
396→        CloudError::JsonParse { source } => crate::error::Error::InvalidResponse {
397→            message: format!("Failed to parse response: {source}"),
398→        },
399→    }
400→}
